from decimal import Decimal

from sqlalchemy import select
from sqlalchemy.orm import Session

from app.models import Cart, Product


def price_cart(session: Session, cart: Cart) -> Decimal:
    ids = [line.product_id for line in cart.lines]
    products = {p.id: p for p in session.scalars(select(Product).where(Product.id.in_(ids)))}
    return sum((products[line.product_id].unit_price * line.quantity for line in cart.lines), Decimal("0"))

import csv

from django.core.management.base import BaseCommand

from crm.models import Contact


class Command(BaseCommand):
    help = "Import contacts from a CSV export"

    def add_arguments(self, parser):
        parser.add_argument("path")

    def handle(self, *args, path, **options):
        with open(path, newline="") as f:
            for row in csv.DictReader(f):
                Contact.objects.create(
                    email=row["email"].lower(),
                    first_name=row["first_name"],
                    last_name=row["last_name"],
                    company=row.get("company", ""),
                )

