def store_events_chunked(session: Session, events: Iterable[dict], chunk_size: int = 500) -> None:
    for i, payload in enumerate(events, start=1):
        session.add(Event(kind=payload["kind"], data=payload, received_at=utcnow()))
        if i % chunk_size == 0:
            session.commit()
    session.commit()

